Np = 100;
q = (0:4*Np)/(Np+1);
%      -,-,gamma,A,-,peak_pos
par = [1,0,10,   1,0, 8];
eCut = 500;
en=eCut*ones(size(q));
enAv = sum(en)/numel(en);

wt = test_dsho_fun(q,en,par);
plot(q,wt); %[output:87a2d2ee]

Norm = sum(wt)*max(q)/numel(q) %[output:3550e8af]



